import{_ as e,o as r,c as t,al as l}from"./chunks/framework.7vp1BMOE.js";const d=JSON.parse('{"title":"相机","description":"","frontmatter":{},"headers":[],"relativePath":"zh/camera/index.md","filePath":"zh/camera/index.md"}'),n={name:"zh/camera/index.md"};function i(o,a,c,m,h,s){return r(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="相机" tabindex="-1">相机 <a class="header-anchor" href="#相机" aria-label="Permalink to &quot;相机&quot;">​</a></h1><p>相机对许多<a href="./../payloads/use_cases">有效载荷使用</a>很重要，包括绘图和勘测、监视、搜索和救援、作物健康和虫害检测等等。 它们通常安装在一个 <a href="./../advanced/gimbal_control">云台</a>上，它能够提供相机稳定性、点跟踪和独立运动。</p><h2 id="相机类型" tabindex="-1">相机类型 <a class="header-anchor" href="#相机类型" aria-label="Permalink to &quot;相机类型&quot;">​</a></h2><p>PX4 集成了三种类型的相机：</p><ul><li><a href="./../camera/mavlink_v2_camera">MAVLink 相机</a> 支持 <a href="https://mavlink.io/en/services/camera.html" target="_blank" rel="noreferrer">Camera Protocol v2</a> (<strong>推荐</strong>)。</li><li><a href="./../camera/mavlink_v1_camera">简单的 MAVLink 摄像头</a> 支持旧的 <a href="https://mavlink.io/en/services/camera.html" target="_blank" rel="noreferrer">Camera Protocol v1</a>。</li><li><a href="./../camera/fc_connected_camera">Cameras attached to flight controller outputs</a>, which are controlled using the <a href="https://mavlink.io/en/services/camera.html" target="_blank" rel="noreferrer">Camera Protocol v1</a>.</li></ul><p>推荐<a href="./../camera/mavlink_v2_camera">MAVLink 摄像头</a>，因为它们使用简单一致的命令/消息集提供了最广泛的相机功能访问。 如果相机不支持该协议，则可以在一台机载计算机上运行<a href="./../camera/mavlink_v2_camera#camera-managers">摄像机管理器</a>以在 MAVLink 和相机的本机协议之间进行接口交互。</p><h2 id="另见" tabindex="-1">另见 <a class="header-anchor" href="#另见" aria-label="Permalink to &quot;另见&quot;">​</a></h2><ul><li><a href="./../advanced/gimbal_control">云台(相机支架)</a></li><li><a href="./../camera/camera_architecture">相机集成/架构</a> ( PX4 开发者)</li></ul>',8)])])}const f=e(n,[["render",i]]);export{d as __pageData,f as default};
